def move_vehicle_out_of_remarks(conn) -> None:
    """Move the vehicle out of the free text: "Vehicle: MH 12 AB 1234 - note" (written by the first Terminal) and the
    vehicle of a credit bill's details become the sale's own column, upper case with no spaces. Nothing is deleted
    except the "Vehicle: ..." words from remarks; the credit bill details row stays as it was."""

    def clean(text):
        return "".join((text or "").split()).upper() or None

    for sale_id, remarks in conn.execute(sa.text("SELECT id, remarks FROM sales WHERE remarks LIKE 'Vehicle: %'")).fetchall():
        head, _, rest = remarks[len("Vehicle: "):].partition(" - ")
        conn.execute(
            sa.text("UPDATE sales SET vehicle_number = :v, remarks = :r WHERE id = :id"),
            {"v": clean(head), "r": rest.strip() or None, "id": sale_id},
        )
    for sale_id, vehicle in conn.execute(sa.text(
        "SELECT d.sale_id, d.vehicle_no FROM credit_bill_details d JOIN sales s ON s.id = d.sale_id "
        "WHERE s.vehicle_number IS NULL AND d.vehicle_no IS NOT NULL"
    )).fetchall():
        conn.execute(sa.text("UPDATE sales SET vehicle_number = :v WHERE id = :id"), {"v": clean(vehicle), "id": sale_id})


def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    with op.batch_alter_table('sales', schema=None) as batch_op:
        batch_op.add_column(sa.Column('vehicle_number', sa.String(length=32), nullable=True))
        batch_op.create_index(batch_op.f('ix_sales_vehicle_number'), ['vehicle_number'], unique=False)

    # ### end Alembic commands ###

    move_vehicle_out_of_remarks(op.get_bind())


def downgrade() -> None:
    """Downgrade schema."""
    # Put the vehicle back into the free text so going back loses nothing.
    op.get_bind().execute(sa.text(
        "UPDATE sales SET remarks = 'Vehicle: ' || vehicle_number || COALESCE(' - ' || remarks, '') WHERE vehicle_number IS NOT NULL"
    ))
    # ### commands auto generated by Alembic - please adjust! ###
    with op.batch_alter_table('sales', schema=None) as batch_op:
        batch_op.drop_index(batch_op.f('ix_sales_vehicle_number'))
        batch_op.drop_column('vehicle_number')

    # ### end Alembic commands ###
